// SRFI-35 condition system procedures
//
// This module implements the runtime procedures that support the SRFI-35 condition system,
// including the procedures generated by the define-condition-type macro and the core
// condition manipulation procedures.

use crate::diagnostics::{Error as DiagnosticError, Result};
use crate::eval::value::Value;
use crate::eval::Environment;
use crate::stdlib::srfi35_conditions::{
    condition_system, ConditionValue, SimpleCondition, ConditionObject,
    initialize_condition_system,
};
use crate::utils::{string_interner::StringInterner, SymbolId};
use std::collections::HashMap;
use std::sync::Arc;

// ============= MACRO SUPPORT PROCEDURES =============

/// %register-condition-type - registers a new condition type (used by macro expansion)
/// Arguments: type-name supertype-name constructor-name predicate-name field-specs
pub fn primitive_register_condition_type(args: &[Value]) -> Result<Value> {
    if args.len() != 5 {
        return Err(Box::new(DiagnosticError::runtime_error(
            format!("%register-condition-type: expected 5 arguments, got {}", args.len()),
            None,
        )));
    }

    let type_name = match &args[0] {
        Value::Literal(crate::ast::Literal::String(s)) => s.clone(),
        _ => return Err(Box::new(DiagnosticError::runtime_error(
            "%register-condition-type: type name must be a string".to_string(),
            None,
        ))),
    };

    let supertype_name = match &args[1] {
        Value::Literal(crate::ast::Literal::String(s)) => Some(s.clone()),
        Value::Nil => None,
        _ => return Err(Box::new(DiagnosticError::runtime_error(
            "%register-condition-type: supertype name must be a string or nil".to_string(),
            None,
        ))),
    };

    let constructor_name = match &args[2] {
        Value::Literal(crate::ast::Literal::String(s)) => s.clone(),
        _ => return Err(Box::new(DiagnosticError::runtime_error(
            "%register-condition-type: constructor name must be a string".to_string(),
            None,
        ))),
    };

    let predicate_name = match &args[3] {
        Value::Literal(crate::ast::Literal::String(s)) => s.clone(),
        _ => return Err(Box::new(DiagnosticError::runtime_error(
            "%register-condition-type: predicate name must be a string".to_string(),
            None,
        ))),
    };

    // Parse field specifications: list of (field-name accessor-name) pairs
    let field_specs = parse_field_specs(&args[4])?;

    // Register the condition type
    let system = condition_system();
    let field_spec_strs: Vec<(&str, &str)> = field_specs
        .iter()
        .map(|(f, a)| (f.as_str(), a.as_str()))
        .collect();

    let type_id = system.registry.register_type(
        &type_name,
        supertype_name.as_deref(),
        &constructor_name,
        &predicate_name,
        field_spec_strs,
    )?;

    // Return the condition type object
    Ok(Value::ConditionType(type_id))
}

/// %get-condition-type - retrieves a condition type by name (used by macro expansion)
pub fn primitive_get_condition_type(args: &[Value]) -> Result<Value> {
    if args.len() != 1 {
        return Err(Box::new(DiagnosticError::runtime_error(
            format!("%get-condition-type: expected 1 argument, got {}", args.len()),
            None,
        )));
    }

    let type_name = match &args[0] {
        Value::Literal(crate::ast::Literal::String(s)) => s.clone(),
        _ => return Err(Box::new(DiagnosticError::runtime_error(
            "%get-condition-type: type name must be a string".to_string(),
            None,
        ))),
    };

    let system = condition_system();
    if let Some(type_id) = system.registry.get_type_id(&type_name) {
        Ok(Value::ConditionType(type_id))
    } else {
        Err(Box::new(DiagnosticError::runtime_error(
            format!("Unknown condition type: {}", type_name),
            None,
        )))
    }
}

/// %make-condition - creates a condition object (used by macro expansion)
/// Arguments: type-name field-bindings
pub fn primitive_make_condition(args: &[Value]) -> Result<Value> {
    if args.len() != 2 {
        return Err(Box::new(DiagnosticError::runtime_error(
            format!("%make-condition: expected 2 arguments, got {}", args.len()),
            None,
        )));
    }

    let type_name = match &args[0] {
        Value::Literal(crate::ast::Literal::String(s)) => s.clone(),
        _ => return Err(Box::new(DiagnosticError::runtime_error(
            "%make-condition: type name must be a string".to_string(),
            None,
        ))),
    };

    // Parse field bindings: list of (field-name . value) pairs
    let field_bindings = parse_field_bindings(&args[1])?;

    let system = condition_system();
    let type_id = system.registry.get_type_id(&type_name)
        .ok_or_else(|| DiagnosticError::runtime_error(
            format!("Unknown condition type: {}", type_name),
            None,
        ))?;

    // Convert field names to symbol IDs
    let mut fields = HashMap::new();
    for (field_name, value) in field_bindings {
        let field_symbol = system.registry.get_interner().intern(&field_name);
        fields.insert(field_symbol, value);
    }

    let simple_condition = SimpleCondition::new(type_id, fields);
    let condition_value = ConditionValue::new(ConditionObject::simple(simple_condition));

    Ok(Value::Condition(Arc::new(condition_value)))
}

// ============= CORE CONDITION PROCEDURES =============

/// condition - creates a compound condition from multiple conditions
pub fn primitive_condition(args: &[Value]) -> Result<Value> {
    crate::stdlib::srfi35_conditions::condition_procedure(args)
}

/// simple-conditions - extracts simple conditions from a compound condition
pub fn primitive_simple_conditions(args: &[Value]) -> Result<Value> {
    crate::stdlib::srfi35_conditions::simple_conditions_procedure(args)
}

/// condition? - tests if an object is a condition
pub fn primitive_condition_p(args: &[Value]) -> Result<Value> {
    crate::stdlib::srfi35_conditions::condition_predicate(args)
}

/// condition-has-type? - tests if a condition has a specific type
pub fn primitive_condition_has_type_p(args: &[Value]) -> Result<Value> {
    crate::stdlib::srfi35_conditions::condition_has_type_procedure(args)
}

/// extract-condition - extracts conditions of a specific type
pub fn primitive_extract_condition(args: &[Value]) -> Result<Value> {
    crate::stdlib::srfi35_conditions::extract_condition_procedure(args)
}

/// condition-ref - accesses a field value from a condition
pub fn primitive_condition_ref(args: &[Value]) -> Result<Value> {
    crate::stdlib::srfi35_conditions::condition_ref_procedure(args)
}

// ============= STANDARD CONDITION CONSTRUCTORS =============

/// make-condition - creates a root condition (no fields)
pub fn primitive_make_condition_root(args: &[Value]) -> Result<Value> {
    if !args.is_empty() {
        return Err(Box::new(DiagnosticError::runtime_error(
            format!("make-condition: expected 0 arguments, got {}", args.len()),
            None,
        )));
    }

    let system = condition_system();
    let simple_condition = SimpleCondition::new(system.standard_types.condition, HashMap::new());
    let condition_value = ConditionValue::new(ConditionObject::simple(simple_condition));

    Ok(Value::Condition(Arc::new(condition_value)))
}

/// make-message-condition - creates a message condition
pub fn primitive_make_message_condition(args: &[Value]) -> Result<Value> {
    if args.len() != 1 {
        return Err(Box::new(DiagnosticError::runtime_error(
            format!("make-message-condition: expected 1 argument, got {}", args.len()),
            None,
        )));
    }

    let message = args[0].clone();
    let system = condition_system();
    let message_field = system.registry.get_interner().intern("message");
    
    let mut fields = HashMap::new();
    fields.insert(message_field, message);

    let simple_condition = SimpleCondition::new(system.standard_types.message, fields);
    let condition_value = ConditionValue::new(ConditionObject::simple(simple_condition));

    Ok(Value::Condition(Arc::new(condition_value)))
}

