// ============= STANDARD CONDITION PREDICATES =============

/// message-condition? - tests if object is a message condition
pub fn primitive_message_condition_p(args: &[Value]) -> Result<Value> {
    if args.len() != 1 {
        return Err(Box::new(DiagnosticError::runtime_error(
            format!("message-condition?: expected 1 argument, got {}", args.len()),
            None,
        )));
    }

    match &args[0] {
        Value::Condition(condition_value) => {
            let system = condition_system();
            Ok(Value::boolean(
                condition_value.condition.has_type(system.standard_types.message, &system.registry)
            ))
        }
        _ => Ok(Value::boolean(false)),
    }
}

