#[cfg(test)]
mod tests {
    use super::*;
    use crate::utils::string_interner::StringInterner;

    #[test]
    fn test_register_condition_type() {
        let interner = Arc::new(StringInterner::new());
        initialize_condition_system(interner).unwrap();
        
        let args = vec![
            Value::string("&my-error".to_string()),
            Value::string("&error".to_string()),
            Value::string("make-my-error".to_string()),
            Value::string("my-error?".to_string()),
            Value::list_from_vec(vec![]), // No fields
        ];
        
        let result = primitive_register_condition_type(&args);
        assert!(result.is_ok());
        
        match result.unwrap() {
            Value::ConditionType(_) => {}, // Success
            _ => panic!("Expected condition type"),
        }
    }

    #[test]
    fn test_make_message_condition() {
        let interner = Arc::new(StringInterner::new());
        initialize_condition_system(interner).unwrap();
        
        let args = vec![Value::string("Test message".to_string())];
        let result = primitive_make_message_condition(&args);
        
        assert!(result.is_ok());
        match result.unwrap() {
            Value::Condition(_) => {}, // Success
            _ => panic!("Expected condition object"),
        }
    }

    #[test]
    fn test_condition_predicate() {
        let interner = Arc::new(StringInterner::new());
        initialize_condition_system(interner).unwrap();
        
        // Test with a condition object
        let condition = primitive_make_message_condition(&[Value::string("Test".to_string())]).unwrap();
        let result = primitive_condition_p(&[condition]);
        assert_eq!(result.unwrap(), Value::boolean(true));
        
        // Test with a non-condition object
        let result = primitive_condition_p(&[Value::integer(42)]);
        assert_eq!(result.unwrap(), Value::boolean(false));
    }
}